#!/usr/bin/env python3
'''P0 行为验收组：删除恢复与错误合同。

覆盖 A09、A10。仅使用 Python 3.12 标准库并复用 acceptance/common.py：
A09 通过真实 HTML 保存/删除/恢复/归类删除表单验证软删除、归类迁移与
跨重启持久化；A10 同时验证 JSON 未知 id、畸形请求以及 HTML 表单校验与
恢复。以 --case 派发，未知用例显式失败；每个用例对真实目标执行正向与
硬负向行为断言，向 stdout 输出单个 atlas.acceptance-result.v1 JSON，失
败时以非零码退出。
'''

from __future__ import annotations

import os
import re
import sys
import uuid
from html.parser import HTMLParser
from urllib.parse import parse_qsl, quote, urlsplit

_THIS_DIR = os.path.dirname(os.path.abspath(__file__))
if _THIS_DIR not in sys.path:
    sys.path.insert(0, _THIS_DIR)

import common

_NUMBER_RE = re.compile('[0-9]+')
_VOID_TAGS = frozenset({
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
})


def _normalize_space(value):
    return ' '.join(str(value or '').split())


class _Field:
    def __init__(self, attrs):
        self.attrs = attrs
        self.name = attrs.get('name')
        self.value = attrs.get('value', '')
        self.type = (attrs.get('type') or 'text').lower()
        self.checked = 'checked' in attrs


class _Option:
    def __init__(self, attrs):
        self.attrs = attrs
        self.value = attrs.get('value')
        self.text = ''
        self.selected = 'selected' in attrs

    def resolved_value(self):
        if self.value is not None:
            return self.value
        return self.text.strip()


class _Select:
    def __init__(self, attrs):
        self.attrs = attrs
        self.name = attrs.get('name')
        self.options = []

    def selected_value(self):
        for option in self.options:
            if option.selected:
                return option.resolved_value()
        if self.options:
            return self.options[0].resolved_value()
        return ''


class _Textarea:
    def __init__(self, attrs):
        self.attrs = attrs
        self.name = attrs.get('name')
        self.text = ''


class _Form:
    def __init__(self, attrs):
        self.attrs = attrs
        self.action = (attrs.get('action') or '').strip()
        self.method = (attrs.get('method') or 'get').strip().lower()
        self.testid = attrs.get('data-testid') or ''
        self.fields = []
        self.selects = []
        self.textareas = []

    def has_name(self, name):
        if any(field.name == name for field in self.fields):
            return True
        if any(select.name == name for select in self.selects):
            return True
        return any(textarea.name == name for textarea in self.textareas)

    def value(self, name):
        for field in reversed(self.fields):
            if field.name == name:
                return field.value
        for select in reversed(self.selects):
            if select.name == name:
                return select.selected_value()
        for textarea in reversed(self.textareas):
            if textarea.name == name:
                return textarea.text
        return None


class _Anchor:
    def __init__(self, attrs):
        self.attrs = attrs
        self.href = attrs.get('href') or ''
        self.testid = attrs.get('data-testid') or ''
        self.text = ''


class _Row:
    def __init__(self, attrs):
        self.attrs = attrs
        self.record_id = attrs.get('data-record-id') or ''
        self.anchors = []
        self.text = ''


def _action_path(action):
    text = (action or '').strip()
    if not text:
        return ''
    try:
        path = urlsplit(text).path
    except ValueError:
        return text
    if not path:
        return ''
    if not path.startswith('/'):
        path = '/' + path
    return path.rstrip('/') or '/'


def _path_of(href):
    try:
        path = urlsplit(href).path
    except ValueError:
        return ''
    if not path:
        return ''
    if not path.startswith('/'):
        path = '/' + path
    return path.rstrip('/') or '/'


def _form_path(form, default):
    action = (form.action or '').strip()
    return action if action else default


class _Document:
    def __init__(self):
        self.forms = []
        self.anchors = []
        self.rows = []
        self.testids = []
        self.start_tags = []
        self.text = ''

    def save_form(self):
        for form in self.forms:
            if form.method == 'post' and _action_path(form.action) == '/bookmarks/new':
                return form
        for form in self.forms:
            if form.method == 'post' and form.has_name('url'):
                return form
        return None


class _HtmlReader(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.doc = _Document()
        self._form = None
        self._select = None
        self._option = None
        self._textarea = None
        self._anchor = None
        self._row = None
        self._testid_stack = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attributes = {
            str(key).lower(): ('' if value is None else value)
            for key, value in attrs
        }
        self.doc.start_tags.append((tag, attributes))
        testid = attributes.get('data-testid') or ''
        if testid:
            entry = {'tag': tag, 'attrs': attributes, 'text': ''}
            self.doc.testids.append(entry)
            if tag not in _VOID_TAGS:
                self._testid_stack.append((tag, entry))
        if tag == 'form':
            self._finish_form()
            self._form = _Form(attributes)
        elif tag == 'input':
            if self._form is not None:
                self._form.fields.append(_Field(attributes))
        elif tag == 'select':
            self._finish_select()
            if self._form is not None:
                self._select = _Select(attributes)
        elif tag == 'option':
            self._finish_option()
            if self._select is not None:
                self._option = _Option(attributes)
        elif tag == 'textarea':
            self._finish_textarea()
            if self._form is not None:
                self._textarea = _Textarea(attributes)
        elif tag == 'a':
            self._finish_anchor()
            self._anchor = _Anchor(attributes)
        elif tag == 'tr' and testid == 'record-row':
            self._finish_row()
            self._row = _Row(attributes)

    def handle_data(self, data):
        if not data:
            return
        self.doc.text += data
        if self._row is not None:
            self._row.text += data
        if self._anchor is not None:
            self._anchor.text += data
        if self._option is not None:
            self._option.text += data
        if self._textarea is not None:
            self._textarea.text += data
        for _, entry in self._testid_stack:
            entry['text'] += data

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == 'a':
            self._finish_anchor()
        elif tag == 'option':
            self._finish_option()
        elif tag == 'select':
            self._finish_select()
        elif tag == 'textarea':
            self._finish_textarea()
        elif tag == 'form':
            self._finish_form()
        elif tag == 'tr':
            self._finish_row()
        if tag in _VOID_TAGS:
            return
        if self._testid_stack and self._testid_stack[-1][0] == tag:
            self._testid_stack.pop()

    def _finish_option(self):
        if self._option is None:
            return
        option = self._option
        self._option = None
        if self._select is not None:
            self._select.options.append(option)

    def _finish_select(self):
        self._finish_option()
        if self._select is None:
            return
        select = self._select
        self._select = None
        if self._form is not None:
            self._form.selects.append(select)

    def _finish_textarea(self):
        if self._textarea is None:
            return
        textarea = self._textarea
        self._textarea = None
        if self._form is not None:
            self._form.textareas.append(textarea)

    def _finish_anchor(self):
        if self._anchor is None:
            return
        anchor = self._anchor
        self._anchor = None
        self.doc.anchors.append(anchor)
        if self._row is not None:
            self._row.anchors.append(anchor)

    def _finish_row(self):
        if self._row is None:
            return
        row = self._row
        self._row = None
        self.doc.rows.append(row)

    def _finish_form(self):
        self._finish_select()
        self._finish_textarea()
        if self._form is None:
            return
        form = self._form
        self._form = None
        self.doc.forms.append(form)

    def finalize(self):
        self._finish_anchor()
        self._finish_row()
        self._finish_form()


def _parse_html(text):
    reader = _HtmlReader()
    reader.feed(text or '')
    reader.close()
    reader.finalize()
    return reader.doc


def _form_fields(form, overrides=None, omit=()):
    fields = {}
    for field in form.fields:
        name = field.name
        if not name:
            continue
        if field.type in ('submit', 'button', 'reset', 'file', 'image'):
            continue
        if field.type in ('checkbox', 'radio') and not field.checked:
            continue
        fields[name] = field.value
    for select in form.selects:
        if select.name:
            fields[select.name] = select.selected_value()
    for textarea in form.textareas:
        if textarea.name:
            fields[textarea.name] = textarea.text
    if overrides:
        for key, value in overrides.items():
            name = str(key)
            if value is None:
                fields.pop(name, None)
            else:
                fields[name] = str(value)
    for name in omit:
        fields.pop(name, None)
    return fields


def _first_form(doc, testid):
    for form in doc.forms:
        if form.testid == testid:
            return form
    return None


def _form_for_category(doc, testid, category_id):
    forms = [
        form for form in doc.forms
        if form.testid == testid and form.has_name('category_id')
    ]
    for form in forms:
        if form.value('category_id') == category_id:
            return form
    if len(forms) == 1:
        return forms[0]
    return None


def _find_record_form(doc, testid, record_id):
    for form in doc.forms:
        if form.testid == testid and form.value('record_id') == record_id:
            return form
    return None


def _form_error_text(doc):
    parts = []
    for entry in doc.testids:
        testid = (entry['attrs'].get('data-testid') or '').lower()
        if testid == 'form-error' or 'form-error' in testid:
            text = _normalize_space(entry['text'])
            if text:
                parts.append(text)
    return ' '.join(parts)


def _category_count_values(doc):
    result = {}
    for entry in doc.testids:
        if entry['attrs'].get('data-testid') != 'category-count':
            continue
        category_id = entry['attrs'].get('data-category-id')
        if not category_id:
            continue
        numbers = _NUMBER_RE.findall(entry['text'])
        value = int(numbers[-1]) if numbers else None
        result.setdefault(category_id, []).append(value)
    return result


def _row_ids(doc):
    return {row.record_id for row in doc.rows if row.record_id}


def _row_for_url(doc, url):
    for row in doc.rows:
        for anchor in row.anchors:
            if anchor.testid == 'record-open-link' and anchor.href == url:
                return row
    for row in doc.rows:
        for anchor in row.anchors:
            if anchor.href == url:
                return row
    return None


def _select_values(form, name):
    for select in form.selects:
        if select.name == name:
            return [option.resolved_value() for option in select.options]
    return []


def _unique_url(tag):
    token = f'{tag}-{uuid.uuid4().hex[:12]}'
    return f'https://{token}.atlas-acceptance.example/{token}'


def _unique_category(tag):
    return f'atlas-{tag}-{uuid.uuid4().hex[:10]}'


def _safe_json(response):
    try:
        return response.json()
    except Exception:
        return None


def _extract_record(payload):
    if isinstance(payload, dict):
        for key in ('bookmark', 'record', 'data', 'item'):
            value = payload.get(key)
            if isinstance(value, dict):
                return value
        return payload
    return None


def _extract_category(payload):
    if isinstance(payload, dict):
        value = payload.get('category')
        if isinstance(value, dict):
            return value
        return payload
    return None


def _extract_list(payload, keys):
    if isinstance(payload, list):
        return payload
    if isinstance(payload, dict):
        for key in keys:
            value = payload.get(key)
            if isinstance(value, list):
                return value
    return None


def _record_id(record):
    if isinstance(record, dict) and record.get('id') is not None:
        return str(record['id'])
    return None


def _record_url(record):
    if isinstance(record, dict) and record.get('url') is not None:
        return str(record['url'])
    return None


def _record_title(record):
    if isinstance(record, dict) and record.get('title') is not None:
        return str(record['title'])
    return None


def _record_description(record):
    if isinstance(record, dict):
        for key in ('description', 'desc'):
            if record.get(key) is not None:
                return str(record[key])
    return None


def _record_category_name(record, categories):
    if not isinstance(record, dict):
        return None
    by_id = {}
    names = set()
    for item in categories or []:
        if isinstance(item, dict) and item.get('id') is not None:
            if item.get('name') is not None:
                by_id[str(item['id'])] = str(item['name'])
                names.add(str(item['name']))
    for key in ('category', 'category_name', 'categoryName'):
        value = record.get(key)
        if isinstance(value, str):
            if value in names:
                return value
            if value in by_id:
                return by_id[value]
            return value
        if isinstance(value, dict) and value.get('name') is not None:
            return str(value['name'])
    for key in ('category_id', 'categoryId'):
        value = record.get(key)
        if value is not None and str(value) in by_id:
            return by_id[str(value)]
    return None


def _record_category_id(record):
    if not isinstance(record, dict):
        return None
    for key in ('category_id', 'categoryId'):
        value = record.get(key)
        if value is not None:
            return str(value)
    value = record.get('category')
    if isinstance(value, dict) and value.get('id') is not None:
        return str(value['id'])
    return None


def _category_names(categories):
    return {
        str(item['name']) for item in categories
        if isinstance(item, dict) and item.get('name') is not None
    }


def _category_ids(categories):
    return {
        str(item['id']) for item in categories
        if isinstance(item, dict) and item.get('id') is not None
    }


def _find_category_by_name(categories, name):
    if name is None:
        return None
    target = str(name).casefold()
    for item in categories:
        if isinstance(item, dict) and item.get('name') is not None:
            if str(item['name']).casefold() == target:
                return item
    return None


def _find_category_by_id(categories, category_id):
    if category_id is None:
        return None
    target = str(category_id)
    for item in categories:
        if isinstance(item, dict) and item.get('id') is not None:
            if str(item['id']) == target:
                return item
    return None


def _default_category(categories):
    for item in categories:
        if isinstance(item, dict) and item.get('is_default'):
            return item
    return _find_category_by_name(categories, common.DEFAULT_CATEGORY)


def _error_code(response):
    payload = _safe_json(response)
    if isinstance(payload, dict):
        error = payload.get('error')
        if isinstance(error, dict) and error.get('code') is not None:
            return str(error['code'])
        for key in ('code', 'error_code'):
            if payload.get(key) is not None:
                return str(payload[key])
    return None


def _bookmark_path(bookmark_id):
    return '/api/bookmarks/' + quote(str(bookmark_id), safe='')


def _move_path(bookmark_id):
    return _bookmark_path(bookmark_id) + '/move'


def _category_path(category_id):
    return '/api/categories/' + quote(str(category_id), safe='')


def _record_ids(records):
    return {
        record_id for record_id in (_record_id(record) for record in records)
        if record_id
    }


def _record_urls(records):
    return {
        url for url in (_record_url(record) for record in records)
        if url
    }


def _fetch_bookmarks(client, recorder, aid, params=None):
    response = client.get('/api/bookmarks', params=params)
    recorder.expect_status(response, 200, aid=f'{aid}-status')
    payload = _safe_json(response)
    records = _extract_list(payload, ('bookmarks', 'items', 'data', 'records'))
    recorder.check(
        f'{aid}-shape',
        isinstance(records, list),
        f'GET /api/bookmarks 必须返回 JSON 数组，实际 {type(payload).__name__}',
    )
    return records if isinstance(records, list) else []


def _fetch_categories(client, recorder, aid):
    response = client.get('/api/categories')
    recorder.expect_status(response, 200, aid=f'{aid}-status')
    payload = _safe_json(response)
    categories = _extract_list(payload, ('categories', 'items', 'data'))
    recorder.check(
        f'{aid}-shape',
        isinstance(categories, list),
        f'GET /api/categories 必须返回 JSON 数组，实际 {type(payload).__name__}',
    )
    return categories if isinstance(categories, list) else []


def _category_signature(categories):
    items = []
    for item in categories:
        if not isinstance(item, dict):
            continue
        items.append((
            str(item.get('id')),
            str(item.get('name')),
            bool(item.get('is_default')),
            item.get('count'),
        ))
    return tuple(sorted(items, key=lambda entry: (entry[0], entry[1])))


def _record_map(records, categories):
    result = {}
    for record in records:
        record_id = _record_id(record)
        if record_id:
            result[record_id] = _record_category_name(record, categories)
    return result


def _snapshot(client, recorder, aid):
    categories = _fetch_categories(client, recorder, f'{aid}-categories')
    records = _fetch_bookmarks(
        client, recorder, f'{aid}-records', params={'include_trashed': 1}
    )
    return (_category_signature(categories), _record_map(records, categories))


def _check_unchanged(recorder, aid, before, after, label):
    recorder.check(
        f'{aid}-categories-unchanged',
        before[0] == after[0],
        f'{label} 后分类集合（含计数）不变：{len(before[0])} -> {len(after[0])}',
    )
    recorder.check(
        f'{aid}-records-unchanged',
        before[1] == after[1],
        f'{label} 后记录集合与归类归属不变：{len(before[1])} -> {len(after[1])}',
    )


def _follow_303(client, recorder, response, aid, expected_path=None, expected_query=None):
    recorder.expect_status(response, 303, aid=f'{aid}-status')
    location = response.location
    if not recorder.check(
        f'{aid}-location',
        bool(location),
        f'303 响应必须带 Location，实际 {location!r}',
    ):
        return None, None
    parts = urlsplit(location)
    if expected_path is not None:
        actual_path = parts.path.rstrip('/') or '/'
        wanted_path = expected_path.rstrip('/') or '/'
        recorder.check(
            f'{aid}-path',
            actual_path == wanted_path,
            f'303 Location={location!r} 的路径={actual_path!r}（期望 {wanted_path!r}）',
        )
    if expected_query:
        actual_query = dict(parse_qsl(parts.query, keep_blank_values=True))
        for key, value in expected_query.items():
            actual_value = actual_query.get(key)
            recorder.check(
                f'{aid}-query-{key}',
                actual_value == value,
                f'303 Location={location!r} 的 {key}={actual_value!r}（期望 {value!r}）',
            )
    page = client.get(location, accept='text/html')
    recorder.expect_status(page, 200, aid=f'{aid}-follow-status')
    return page, location


def _home_page(client, recorder, aid, params=None):
    response = client.get('/', params=params, accept='text/html')
    recorder.expect_status(response, 200, aid=f'{aid}-status')
    recorder.check(
        f'{aid}-content-type',
        'text/html' in response.content_type.lower(),
        f'GET / Content-Type={response.content_type!r}',
    )
    return _parse_html(response.text)


def _categories_page(client, recorder, aid):
    response = client.get('/categories', accept='text/html')
    recorder.expect_status(response, 200, aid=f'{aid}-status')
    recorder.check(
        f'{aid}-content-type',
        'text/html' in response.content_type.lower(),
        f'GET /categories Content-Type={response.content_type!r}',
    )
    return _parse_html(response.text)


def _expect_html_error(recorder, response, aid, label, expected_status):
    recorder.check(
        f'{aid}-no-5xx',
        response.status < 500,
        f'{label} -> HTTP {response.status}（校验类错误不得产生 5xx）',
    )
    recorder.expect_status(
        response,
        expected_status,
        aid=f'{aid}-status',
        detail=f'{label} -> HTTP {response.status}（期望 {expected_status}）',
    )
    doc = _parse_html(response.text)
    error_text = _form_error_text(doc)
    recorder.check(
        f'{aid}-form-error',
        bool(error_text),
        f'{label} 显示可读 form-error，实际 {error_text!r}',
    )
    return doc


def _get_record_json(client, recorder, aid, record_id):
    response = client.get(_bookmark_path(record_id))
    recorder.expect_status(response, 200, aid=f'{aid}-status')
    payload = _safe_json(response)
    record = _extract_record(payload)
    recorder.check(
        f'{aid}-shape',
        isinstance(record, dict),
        f'GET /api/bookmarks/{record_id} 返回 JSON 对象，实际 {type(payload).__name__}',
    )
    return record if isinstance(record, dict) else None


def _save_form_from_home(client, recorder, aid, params=None):
    page = client.get('/', params=params, accept='text/html')
    recorder.expect_status(page, 200, aid=f'{aid}-status')
    doc = _parse_html(page.text)
    form = doc.save_form()
    recorder.check(
        f'{aid}-save-form',
        form is not None,
        '首页含 action=/bookmarks/new 且 method=post 的真实保存表单',
    )
    return doc, form


def _check_json_error(recorder, response, prefix, expected_status, expected_code, label):
    recorder.check(
        f'{prefix}-no-5xx',
        response.status < 500,
        f'{label} -> HTTP {response.status}（校验类错误不得产生 5xx）',
    )
    recorder.expect_status(
        response,
        expected_status,
        aid=f'{prefix}-status',
        detail=f'{label} -> HTTP {response.status}（期望 {expected_status}）',
    )
    code = _error_code(response)
    recorder.check(
        f'{prefix}-code',
        code == expected_code,
        f'{label} 错误码={code!r}（期望 {expected_code}）',
    )


def _a09_live_flow(client, recorder):
    health = client.get('/api/health')
    recorder.expect_status(health, 200, aid='a09-live-health-status')

    _, save_form = _save_form_from_home(client, recorder, 'a09-live')
    if save_form is None:
        return

    name = _unique_category('a09-live')
    url = _unique_url('a09-live')
    title = f'A09 恢复标题 {uuid.uuid4().hex[:8]}'
    description = f'A09 恢复描述 {uuid.uuid4().hex[:8]}'
    response = client.post_form(
        _form_path(save_form, '/bookmarks/new'),
        _form_fields(save_form, {
            'url': url,
            'title': title,
            'description': description,
            'category': name,
        }),
        follow_redirects=False,
        accept='text/html',
