                'a10-html-invalid-url-retained-description',
                retained_description == html_description,
                f'错误页保留 description={retained_description!r}（期望 {html_description!r}）',
            )
        after_invalid_state = _snapshot(client, recorder, 'a10-html-after-invalid')
        _check_unchanged(
            recorder, 'a10-html-invalid-url', before_html_state, after_invalid_state,
            'HTML 非法 URL',
        )
        after_invalid_records = _fetch_bookmarks(
            client, recorder, 'a10-html-after-invalid-records',
            params={'include_trashed': 1},
        )
        recorder.check(
            'a10-html-invalid-url-not-written',
            bad_url not in _record_urls(after_invalid_records),
