        )

        if error_form is None:
            return
        response = client.post_form(
            _form_path(error_form, '/bookmarks/new'),
            _form_fields(error_form, {'url': corrected_url}),
            follow_redirects=False,
            accept='text/html',
        )
        page, _ = _follow_303(
            client, recorder, response, 'a10-html-corrected-save', expected_path='/'
        )
