                )

        categories_page = _categories_page(
            client, recorder, 'a10-categories-page'
        )
        create_form = _first_form(categories_page, 'category-create-form')
        if not recorder.check(
            'a10-category-create-form',
            create_form is not None and create_form.has_name('name'),
