        ):
            return
        before_category_state = _snapshot(
            client, recorder, 'a10-category-before'
        )
        bad_name = 'x' * 121
        response = client.post_form(
            _form_path(create_form, '/categories'),
            _form_fields(create_form, {'name': bad_name}),
            follow_redirects=False,
            accept='text/html',
        )
        error_doc = _expect_html_error(
            recorder, response, 'a10-category-invalid', 'HTML 归类非法 name', 400
        )
        error_form = _first_form(error_doc, 'category-create-form')
        recorder.check(
            'a10-category-invalid-form',
            error_form is not None,
            'HTML 归类非法 name 错误页保留 category-create-form',
        )
        if error_form is not None:
            retained_name = error_form.value('name')
            recorder.check(
                'a10-category-invalid-retained',
                retained_name == bad_name,
                f'错误页保留 name={retained_name!r}（期望 {bad_name!r}）',
            )
        after_category_state = _snapshot(
            client, recorder, 'a10-category-after'
        )
        _check_unchanged(
            recorder, 'a10-category-invalid', before_category_state,
            after_category_state, 'HTML 归类非法 name',
        )
        categories_after = _fetch_categories(
            client, recorder, 'a10-category-after-list'
        )
        recorder.check(
            'a10-category-not-created',
            _find_category_by_name(categories_after, bad_name) is None,
            f'非法 name={bad_name!r} 未被创建为归类',
        )
    finally:
        client.close()


_HANDLERS = {
    'A09': _case_a09,
    'A10': _case_a10,
}


def main(argv=None):
    args = common.parse_case_args(argv)
    recorder = common.Recorder(args.case)
    handler = _HANDLERS.get(args.case)
    if handler is None:
        recorder.check(
            'dispatch',
            False,
            f'acceptance/p0_recovery.py 不实现用例 {args.case}（应由其他程序派发）',
        )
    else:
        try:
            handler(args, recorder)
        except common.AcceptanceError as exc:
            recorder.check('infrastructure', False, f'验收基础设施错误：{exc}')
        except Exception as exc:
            recorder.check(
                'unexpected-error',
                False,
                f'未预期错误：{type(exc).__name__}: {exc}',
            )
    return recorder.finish(args.case)


if __name__ == '__main__':
    sys.exit(main())
